(6311781, 935446, 101707, '<td valign="top">How very clever and so well done! a 10 from me.</td>', 'How very clever and so well done! a 10 from me.', '2011-02-14 00:05:09.000000', NULL, 1),
(6311792, 935358, 83313, '<td valign="top">I can see how you felt this suited, but the composition strikes me as centered comp, not really ROT. My eye is drawn to that ornate entryway, which is very much centered.</td>', 'I can see how you felt this suited, but the composition strikes me as centered comp, not really ROT. My eye is drawn to that ornate entryway, which is very much centered.', '2011-02-14 00:11:48.000000', NULL, 1),
(6311798, 935029, 97225, '<td valign="top">Beautiful photo. Lovely little bird and lovely background.</td>', 'Beautiful photo. Lovely little bird and lovely background.', '2011-02-14 00:16:28.000000', NULL, 1),
(6311804, 935685, 97225, '<td valign="top">Brilliant capture.</td>', 'Brilliant capture.', '2011-02-14 00:18:38.000000', NULL, 1),
(6311815, 935264, 97225, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2011-02-14 00:21:24.000000', NULL, 1),
(6311819, 935453, 97225, '<td valign="top">Beautiful scene. I love the colours and the sky is fantastic.</td>', 'Beautiful scene. I love the colours and the sky is fantastic.', '2011-02-14 00:22:37.000000', NULL, 1),
(6311826, 934936, 97225, '<td valign="top">Beautiful shot. I love those frosty sparkles.</td>', 'Beautiful shot. I love those frosty sparkles.', '2011-02-14 00:24:01.000000', NULL, 1),
(6311830, 934873, 97225, '<td valign="top">Gorgeous.</td>', 'Gorgeous.', '2011-02-14 00:24:39.000000', NULL, 1),
(6311839, 935209, 97225, '<td valign="top">I love whimsical reflections. Very nice!</td>', 'I love whimsical reflections. Very nice!', '2011-02-14 00:26:51.000000', NULL, 1),
(6311843, 935209, 100831, '<td valign="top">I''m a sucker for good reflections.</td>', 'I''m a sucker for good reflections.', '2011-02-14 00:27:38.000000', NULL, 1),
(6311845, 935126, 97225, '<td valign="top">Nice scenery. Those two plants look like they''re facing off for a duel.</td>', 'Nice scenery. Those two plants look like they''re facing off for a duel.', '2011-02-14 00:28:50.000000', NULL, 1),
(6311848, 935248, 30861, '<td valign="top">This is a lovely image, but the umbrellas in the eyes are really, REALLY unfortunate :-( It''s like she''s an android or something, with some sort of disk-shutter sliding down over her pupils. You can get away with umbrella reflections in eyes, as long as they don''t eclipse the pupils, but this is just... unfortunate :-(<br/> <br/>In all other respects, wonderful image and lovely woman :-)</td>', 'This is a lovely image, but the umbrellas in the eyes are really, REALLY unfortunate :-( It''s like she''s an android or something, with some sort of disk-shutter sliding down over her pupils. You can get away with umbrella reflections in eyes, as long as they don''t eclipse the pupils, but this is just... unfortunate :-( In all other respects, wonderful image and lovely woman :-)', '2011-02-14 00:29:45.000000', NULL, 1),
(6311857, 935689, 30861, '<td valign="top">This is a centered composition. The fact that some elements of it fall on ROT lines/interstices does not change that. The dominant compositional rule here is "centered". Very nice light, though, very nice, luminous conversion.</td>', 'This is a centered composition. The fact that some elements of it fall on ROT lines/interstices does not change that. The dominant compositional rule here is "centered". Very nice light, though, very nice, luminous conversion.', '2011-02-14 00:32:21.000000', NULL, 1),
(6311859, 934327, 97225, '<td valign="top">Lovely shot. I love the way the water just fades away int the atmosphere.</td>', 'Lovely shot. I love the way the water just fades away int the atmosphere.', '2011-02-14 00:33:26.000000', NULL, 1),
(6311866, 934796, 97225, '<td valign="top">Beautiful play of light and shadow.</td>', 'Beautiful play of light and shadow.', '2011-02-14 00:35:06.000000', NULL, 1),
(6311870, 934264, 94815, '<td valign="top">I don''t know what to do with a great shot like this that misses the topic. These topics are silly sometimes but since it says "RULE of the thirds" I suppose we have to comply. This works for the fifths but misses the thirds. Still a good shot with just a bit of halo at the horizon.</td>', 'I don''t know what to do with a great shot like this that misses the topic. These topics are silly sometimes but since it says "RULE of the thirds" I suppose we have to comply. This works for the fifths but misses the thirds. Still a good shot with just a bit of halo at the horizon.', '2011-02-14 00:38:00.000000', NULL, 1),
