(6317439, 935479, 82282, '<td valign="top">Bokeh seems distracting.  I''d also clone out the white spec floating above the statue.</td>', 'Bokeh seems distracting.  I''d also clone out the white spec floating above the statue.', '2011-02-16 18:07:24.000000', NULL, 1),
(6317538, 934958, 114225, '<td valign="top">Nice colors and mood in this photo.</td>', 'Nice colors and mood in this photo.', '2011-02-16 19:38:30.000000', NULL, 1),
(6317542, 935568, 114225, '<td valign="top">Cute photo for the challenge. Interesting that you went black and white here. Normally I find that B&amp;W works best for highly textured subjects, as it accentuates the details, but it works nicely here too.</td>', 'Cute photo for the challenge. Interesting that you went black and white here. Normally I find that B&W works best for highly textured subjects, as it accentuates the details, but it works nicely here too.', '2011-02-16 19:40:25.000000', NULL, 1),
(6317546, 934264, 114225, '<td valign="top">Great dramatic clouds and excellent contrast to gives this scene a very dynamic feel.</td>', 'Great dramatic clouds and excellent contrast to gives this scene a very dynamic feel.', '2011-02-16 19:40:57.000000', NULL, 1),
(6317548, 935264, 114225, '<td valign="top">Funny, one of my thoughts for his challenge was also some ducks :)<br/>Nice capture. I''m a bit surprised you decided to crop it so tight. I think I would have preferred seeing the lake extend further into the background.</td>', 'Funny, one of my thoughts for his challenge was also some ducks :)Nice capture. I''m a bit surprised you decided to crop it so tight. I think I would have preferred seeing the lake extend further into the background.', '2011-02-16 19:42:02.000000', NULL, 1),
(6317552, 935497, 114225, '<td valign="top">Very nice industrial capture. Did you use a polarizing filter to provide the contrast in the sky?</td>', 'Very nice industrial capture. Did you use a polarizing filter to provide the contrast in the sky?', '2011-02-16 19:42:36.000000', NULL, 1),
(6317553, 935432, 114225, '<td valign="top">Very cool find (no pun intended). I really like how the snow has carved itself out around the structure.</td>', 'Very cool find (no pun intended). I really like how the snow has carved itself out around the structure.', '2011-02-16 19:43:33.000000', NULL, 1),
(6317554, 934722, 114225, '<td valign="top">Excellent capture! That trail of snow definitely makes the photo come alive. Only thing I wish was that the background was slightly more blurred, but i still really like the shot.</td>', 'Excellent capture! That trail of snow definitely makes the photo come alive. Only thing I wish was that the background was slightly more blurred, but i still really like the shot.', '2011-02-16 19:44:30.000000', NULL, 1),
