INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6323204, 935483, 67697, '<td valign="top">Warm and beautiful.  I love the scene and the colors.  The sky and clouds are fabulous too.</td>', 'Warm and beautiful.  I love the scene and the colors.  The sky and clouds are fabulous too.', '2011-02-20 22:57:51.000000', NULL, 1),
(6323206, 935686, 67697, '<td valign="top">Great winter scene.  I like how it appears as tho the cardinal is about to have a conversation with the leaves.</td>', 'Great winter scene.  I like how it appears as tho the cardinal is about to have a conversation with the leaves.', '2011-02-20 22:58:28.000000', NULL, 1),
(6323207, 935620, 67697, '<td valign="top">Love the gorgeous warm glow.  Great use of a silhouette.</td>', 'Love the gorgeous warm glow.  Great use of a silhouette.', '2011-02-20 22:59:03.000000', NULL, 1),
(6323208, 935035, 67697, '<td valign="top">Gorgeous macro.  Makes me hopeful for spring.  Love that orange color.</td>', 'Gorgeous macro.  Makes me hopeful for spring.  Love that orange color.', '2011-02-20 23:00:34.000000', NULL, 1),
(6323325, 935446, 30982, '<td valign="top">Way to go, girl!  I thought this was you-know-who!  Your model did a great job, too.  Congrats!</td>', 'Way to go, girl!  I thought this was you-know-who!  Your model did a great job, too.  Congrats!', '2011-02-21 00:05:41.000000', NULL, 0),
(6323328, 935084, 30982, '<td valign="top">Not flaws at all - in fact, your "botched" parts make this shot work!  Congrats on an excellent picture!</td>', 'Not flaws at all - in fact, your "botched" parts make this shot work!  Congrats on an excellent picture!', '2011-02-21 00:06:40.000000', NULL, 0),
(6323329, 935485, 61084, '<td valign="top">Congrats on the blue. I loved it and was one of your "10''s". :)</td>', 'Congrats on the blue. I loved it and was one of your "10''s". :)', '2011-02-21 00:07:32.000000', NULL, 0),
(6323330, 935446, 67697, '<td valign="top">yay!  Top 10.  It''s so fabulous!  Congrats :)</td>', 'yay!  Top 10.  It''s so fabulous!  Congrats :)', '2011-02-21 00:08:07.000000', NULL, 0),
(6323332, 935620, 67697, '<td valign="top">whoo hoo - top 10!  congrats!</td>', 'whoo hoo - top 10!  congrats!', '2011-02-21 00:08:29.000000', NULL, 0),
(6323334, 934873, 125389, '<td valign="top">I am astounded that you did not ribbon.  I can''t believe it.  It was the best pic.  But then I can''t believe I came in 58th, looking at some of the pictures that scored above me.  Sometimes it is very discouraging, but then I do learn a lot as well.  Good luck next time...this was a really great shot.</td>', 'I am astounded that you did not ribbon.  I can''t believe it.  It was the best pic.  But then I can''t believe I came in 58th, looking at some of the pictures that scored above me.  Sometimes it is very discouraging, but then I do learn a lot as well.  Good luck next time...this was a really great shot.', '2011-02-21 00:09:02.000000', NULL, 0),
(6323338, 934796, 67697, '<td valign="top">It''s a bummer to see this finish so low.  I gave it a 7.  I loved your capture of light and shadow.</td>', 'It''s a bummer to see this finish so low.  I gave it a 7.  I loved your capture of light and shadow.', '2011-02-21 00:10:17.000000', NULL, 0),
(6323340, 935585, 67697, '<td valign="top">you know, I finished one place above you and it''s kind of eerie how similar the photos are.  Go look at the thumbs and you will see how our thirds pieces line up.  Interesting!</td>', 'you know, I finished one place above you and it''s kind of eerie how similar the photos are.  Go look at the thumbs and you will see how our thirds pieces line up.  Interesting!', '2011-02-21 00:12:01.000000', NULL, 0),
(6323342, 935628, 67697, '<td valign="top">aww finished too low.  It''s such a beautiful piece of art.</td>', 'aww finished too low.  It''s such a beautiful piece of art.', '2011-02-21 00:12:56.000000', NULL, 0),
(6323344, 935446, 117534, '<td valign="top">Ohh look at you AGAIN! YAY your HOT HOT HOT... I thought this was a gayban picture! (I mean that as a compliment)  Congratulations!!</td>', 'Ohh look at you AGAIN! YAY your HOT HOT HOT... I thought this was a gayban picture! (I mean that as a compliment)  Congratulations!!', '2011-02-21 00:13:23.000000', NULL, 0),
